files.main.tf:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

resource "aws_instance" "this" {
  count         = 1
  ami           = "ami-0000000000000000"
  instance_type = "t3.medium"
  key_name      = "devguard-key"

  tags = {
    Name = "devguard-app"
  }
}

files.variables.tf:
variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "dev"
}

files.outputs.tf:
output "instance_ids" {
  value = aws_instance.this[*].id
}

output "public_ips" {
  value = aws_instance.this[*].public_ip
}
